create or replace TABLE LDL_PRODUCTION_CLONE_GOOGLE_20260608_1030.P_LEW_CORE.T_WAREHOUSE_RECEIVING_COUNT_TASK_POS (
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'DWH-Mandant; FK auf CLIENT.',
	WH_RCV_CNT_TASK_SID NUMBER(38,0) NOT NULL COMMENT 'Surrogate identifier to be created (country, warehouse, inbound delivery / TaskID and creation date is generally unique).',
	WH_RCV_CNT_TASK_POS_NR NUMBER(38,0) NOT NULL COMMENT 'Position code per receiving count task.',
	WH_LOC_SID NUMBER(38,0) NOT NULL COMMENT 'Warehouse; FK auf LOCATION.',
	WH_DOCKING_GATE_NR VARCHAR(100) COMMENT 'Identifier of the docking gate at the warehouse where the transportation vehicle docks for loading and unloading.',
	ITEM_SID NUMBER(38,0) COMMENT 'Surrogate Key ITEM (eindeutig ueber alle Laender/Mandanten hinweg).',
	DEPARTURE_SUP_SID NUMBER(38,0) COMMENT 'Supplier SID from where the receiving item departed.',
	DEPARTURE_WH_LOC_SID NUMBER(38,0) COMMENT 'Location SID of the warehouse from where the receiving item departed.',
	DEPARTURE_STORE_LOC_SID NUMBER(38,0) COMMENT 'Location SID of the store from where the receiving item departed.',
	DESPATCH_ADVICE_ID NUMBER(28,0) COMMENT 'Reference to a despatch advice, if a despatch advice technically has been used in the counting process.',
	POS_CREATED_DT DATE COMMENT 'Date when the counting task position has been created.',
	POS_STATUS_ID NUMBER(38,0) COMMENT 'Status of the receiving count task position like GR posted, rejected, not valid, open, etc.',
	RCV_RECEIPT_ID NUMBER(38,0) COMMENT 'ID of the generated item receiving record (if an item receiving record has been created).',
	ITEM_RCV_DT DATE COMMENT 'Date of when the item has been received (if an item receiving has been created).',
	PALLET_CNT NUMBER(38,0) COMMENT 'Count of pallets in the task position.',
	CASE_CNT NUMBER(38,0) COMMENT 'Count of cases in the task position.',
	CASE_PER_PALLET_CNT NUMBER(38,0) COMMENT 'Count of cases per pallet.',
	HANDLING_UNIT_NR VARCHAR(100) COMMENT 'Handling unit identifier.',
	HANDLING_UNIT_TYPE_CD VARCHAR(100) COMMENT 'Handling unit type code.',
	PALLET_TYPE_CD VARCHAR(100) COMMENT 'Pallet type code like EU, DD, etc.',
	REJECTED_FG NUMBER(38,0) COMMENT 'Flag for when pallets were rejected.',
	ORDER_RECORD_ID VARCHAR(100) COMMENT 'Order number: src_orig_supplier_nr (4 digits), date (DDMMYY, 6 digits) and counting version number (2 digits) for supllier - Date combination; Wawi: PO_NR.',
	CASE_SIZE_QTY NUMBER(38,5) COMMENT 'Case size quantity of the package unit (Kolli).',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The identifier of the last load run which inserted or updated this row.',
	DWH_CREATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
	constraint PK_T_WAREHOUSE_RECEIVING_COUNT_TASK_POS primary key (WH_RCV_CNT_TASK_SID, WH_RCV_CNT_TASK_POS_NR)
)COMMENT='Table contains position or line-wise data of the counting task / inbound delivery of the receiving pallet from suppliers, store returns, warehouse transfers to warehouses.\n             Source:\n             WAWI table T174_GinCount, T187_FV_Order, T1010_SSCC\n             EWM table /SCDL/DB_PROCI_I, /SCDL/DB_BPLOC, /SCDL/DB_REFDOC, /SCWM/ORDIM_C (TRART = 5/6)'
;
